enum List {
    Cons(i32, Box<List>),
    Nil,
}
use List::{Cons, Nil};

fn sum(list: &List) -> i32 {
    match list {
        Cons(value, rest) => *value + sum(rest),
        Nil => 0,
    }
}

fn length(list: &List) -> u32 {
    match list {
        Cons(_, rest) => 1 + length(rest),
        Nil => 0,
    }
}

fn main() {
    let list = Cons(1, Box::new(Cons(2, Box::new(Cons(3, Box::new(Nil))))));
    println!("sum = {}, length = {}", sum(&list), length(&list));
}
